// Ventana [ahora+23h, ahora+25h): cada evento cae en dos corridas; la idempotencia la da dedupeKey por usuario.
const now = Date.now(), H = 3600000;
const from = new Date(now + 23 * H).toISOString(), to = new Date(now + 25 * H).toISOString();
return [{ json: { from, to, correlationId: 'n8n-wf02-' + new Date(now).toISOString().slice(0, 13) } }];

const token = $('Token').first().json.token, corr = $('Key').first().json.correlationId;
const base = $env.BANDADA_EVENTS_INTERNAL_URL;
const hash = (str) => { let h = 5381; for (const ch of str) h = ((h * 33) ^ ch.charCodeAt(0)) >>> 0; return h.toString(16); };

// UUID determinista (v8) derivado de un texto: los servicios exigen Idempotency-Key con forma de UUID.
function detUuid(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57, h3 = 0x9e3779b9, h4 = 0x85ebca6b;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); h3 = Math.imul(h3 ^ c, 2246822507); h4 = Math.imul(h4 ^ c, 3266489909); }
  h1 = Math.imul(h1 ^ (h2 >>> 15), 2246822507) ^ Math.imul(h3 ^ (h4 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h3 >>> 15), 2246822507) ^ Math.imul(h4 ^ (h1 >>> 13), 3266489909);
  h3 = Math.imul(h3 ^ (h4 >>> 15), 2246822507) ^ Math.imul(h1 ^ (h2 >>> 13), 3266489909);
  h4 = Math.imul(h4 ^ (h1 >>> 15), 2246822507) ^ Math.imul(h2 ^ (h3 >>> 13), 3266489909);
  const hex = [h1, h2, h3, h4].map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0, 8) + '-' + hex.slice(8, 12) + '-8' + hex.slice(13, 16) + '-a' + hex.slice(17, 20) + '-' + hex.slice(20, 32);
}

const out = [];
for (const ev of ($json.items || [])) {
  const userIds = [];
  let cursor = null;
  do {
    const q = '?status=CONFIRMED&limit=50' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : '');
    const page = await this.helpers.httpRequest({ method: 'GET', url: base + '/internal/v1/events/' + ev.id + '/registrations' + q, headers: { Authorization: 'Bearer ' + token, 'X-Correlation-Id': corr }, json: true, timeout: 10000 });
    for (const r of (page.items || [])) userIds.push(r.userId);
    cursor = page.nextCursor || null;
  } while (cursor);
  const unique = [...new Set(userIds)].sort();
  if (!unique.length) continue;
  const laPaz = new Date(new Date(ev.startsAt).getTime() - 4 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 16) + ' (La Paz)';
  out.push({ json: {
    idemKey: detUuid('n8n:wf-02:' + ev.id + ':' + hash(unique.join(','))),
    body: { userIds: unique, type: 'EVENT_REMINDER', dedupeKey: 'reminder:' + ev.id,
      params: { eventTitle: ev.title, startsAt: ev.startsAt, startsAtText: laPaz, venue: ev.venue || '' },
      data: { eventId: ev.id, deepLink: 'bandada://events/' + ev.id } },
  } });
}
return out;
